+
+type requestedReviewers struct {
+	Users []struct {
+		Login string `json:"login"`
+	} `json:"users"`
+}
+
+func runObserve(
+	ctx context.Context,
+	args []string,
+	runner commandRunner,
+	stdout io.Writer,
+) error {
+	opts, err := parseObserveOptions(args)
+	if err != nil {
+		return err
+	}
+	var plan reviewroute.Plan
+	if err := readArtifact(opts.plan, &plan); err != nil {
+		return err
+	}
+	if err := reviewroute.ValidatePlan(plan); err != nil {
+		return refusalError{err}
+	}
+	before, err := fetchPullRequest(ctx, runner, plan.Subject.Repo, plan.Subject.Number)
+	if err != nil {
+		return err
+	}
+	if !strings.EqualFold(before.HeadRefOID, plan.Subject.HeadSHA) {
+		return refusalError{errors.New("review plan is stale before observation")}
+	}
+	reviews, err := fetchReviews(ctx, runner, plan.Subject)
+	if err != nil {
+		return err
+	}
+	comments, err := fetchIssueComments(ctx, runner, plan.Subject)
+	if err != nil {
+		return err
+	}
+	requested, err := fetchRequested(ctx, runner, plan.Subject)
+	if err != nil {
+		return err
+	}
+	evidence := buildPanel(plan, reviews, comments, requested)
+	after, err := fetchPullRequest(ctx, runner, plan.Subject.Repo, plan.Subject.Number)
+	if err != nil {
+		return err
+	}
+	if !strings.EqualFold(before.HeadRefOID, after.HeadRefOID) {
+		return refusalError{errors.New("pull request head changed during observation")}
+	}
+	if err := reviewpanel.Validate(evidence); err != nil {
+		return refusalError{err}
+	}
+	return writeArtifact(opts.out, evidence, nil, stdout)
+}
+
+func parseObserveOptions(args []string) (observeOptions, error) {
+	var opts observeOptions
+	flags := flag.NewFlagSet("observe", flag.ContinueOnError)
+	flags.SetOutput(io.Discard)
+	flags.StringVar(&opts.plan, "plan", "", "ReviewPlanV1 path")
+	flags.StringVar(&opts.out, "out", "", "output ReviewPanelV1 path")
+	if err := flags.Parse(args); err != nil {
+		return observeOptions{}, err
+	}
+	if opts.plan == "" || opts.out == "" {
+		return observeOptions{}, errors.New("-plan and -out are required")
+	}
+	return opts, nil
+}
+
+func fetchReviews(
+	ctx context.Context,
+	runner commandRunner,
+	subject reviewroute.Subject,
+) ([]rawReview, error) {
+	endpoint := fmt.Sprintf("repos/%s/pulls/%d/reviews", subject.Repo, subject.Number)
+	data, err := runner.Run(ctx, "gh", "api", "--paginate", "--slurp", endpoint)
+	if err != nil {
+		return nil, err
+	}
+	var pages [][]rawReview
+	if err := json.Unmarshal(data, &pages); err != nil {
+		return nil, err
+	}
+	var out []rawReview
+	for _, page := range pages {
+		out = append(out, page...)
+	}
+	return out, nil
+}
+
+func fetchIssueComments(
+	ctx context.Context,
+	runner commandRunner,
+	subject reviewroute.Subject,
+) ([]issueComment, error) {
+	endpoint := fmt.Sprintf("repos/%s/issues/%d/comments", subject.Repo, subject.Number)
+	data, err := runner.Run(ctx, "gh", "api", "--paginate", "--slurp", endpoint)
+	if err != nil {
+		return nil, err
+	}
+	var pages [][]issueComment
+	if err := json.Unmarshal(data, &pages); err != nil {
+		return nil, err
+	}
+	var out []issueComment
+	for _, page := range pages {
+		out = append(out, page...)
+	}
+	return out, nil
+}
+
+func fetchRequested(
+	ctx context.Context,
+	runner commandRunner,
+	subject reviewroute.Subject,
+) ([]string, error) {
+	endpoint := fmt.Sprintf("repos/%s/pulls/%d/requested_reviewers",
+		subject.Repo, subject.Number)
+	data, err := runner.Run(ctx, "gh", "api", endpoint)
+	if err != nil {
+		return nil, err
+	}
+	var response requestedReviewers
+	if err := json.Unmarshal(data, &response); err != nil {
+		return nil, err
+	}
+	out := make([]string, 0, len(response.Users))
+	for _, user := range response.Users {
+		out = append(out, user.Login)
+	}
+	return out, nil
+}
+
+func buildPanel(
+	plan reviewroute.Plan,
+	reviews []rawReview,
+	comments []issueComment,
+	requested []string,
+) reviewpanel.Evidence {
+	expected := append([]string{}, plan.Required...)
+	sort.Strings(expected)
+	evidence := reviewpanel.Evidence{
+		SchemaVersion: reviewpanel.SchemaVersion,
+		Subject: reviewpanel.Subject{
+			Repo: plan.Subject.Repo, Number: plan.Subject.Number,
+			HeadSHA: plan.Subject.HeadSHA,
+		},
+		Declaration: reviewpanel.Declaration{
+			Path:     "ReviewPlanV1:" + plan.PlanID,
+			Expected: expected,
+		},
+		Completed: []reviewpanel.Reviewer{},
+		Pending:   []string{},
+		Missing:   []string{},
+		Unknown:   []string{},
+	}
+	if plan.Policy != nil {
+		evidence.Declaration.Revision = fmt.Sprintf("%s@%s",
+			plan.Policy.ID, plan.Policy.Digest)
+	}
+	for _, reviewer := range expected {
+		if completed, ok := latestReview(reviewer, plan.Subject.HeadSHA, reviews); ok {
+			evidence.Completed = append(evidence.Completed, completed)
+			continue
+		}
+		if completed, ok := cleanComment(reviewer, plan.Subject.HeadSHA, comments); ok {
+			evidence.Completed = append(evidence.Completed, completed)
+			continue
+		}
+		if actorPresent(reviewer, requested) {
+			evidence.Pending = append(evidence.Pending, reviewer)
+			continue
+		}
+		evidence.Missing = append(evidence.Missing, reviewer)
+	}
+	return evidence
+}
+
+func latestReview(
+	expected, head string,
+	reviews []rawReview,
+) (reviewpanel.Reviewer, bool) {
+	for index := len(reviews) - 1; index >= 0; index-- {
+		review := reviews[index]
+		if !strings.EqualFold(review.CommitID, head) ||
+			!completedReviewState(review.State) ||
+			!actorMatches(expected, review.User.Login) {
+			continue
+		}
+		return reviewpanel.Reviewer{
+			Name: expected, Actor: review.User.Login,
+			State: strings.ToUpper(review.State), HeadSHA: strings.ToLower(head),
+			ReviewID: review.ID,
+		}, true
+	}
+	return reviewpanel.Reviewer{}, false
+}
+
+func completedReviewState(state string) bool {
+	switch strings.ToUpper(state) {
+	case "APPROVED", "COMMENTED", "CHANGES_REQUESTED":
+		return true
+	}
+	return false
+}
+
+var codexReviewedCommit = regexp.MustCompile(
+	"(?m)^\\*\\*Reviewed commit:\\*\\* `([0-9a-f]{40})`\\r?$",
+)
+
+func cleanComment(
+	expected, head string,
+	comments []issueComment,
+) (reviewpanel.Reviewer, bool) {
+	// Comment-based completion is Codex-specific: Codex emits a structured
+	// clean-review message with a full reviewed commit. Extend this boundary
+	// explicitly if another reviewer gains an equivalent exact-head signal.
+	if expected != "codex" {
+		return reviewpanel.Reviewer{}, false
+	}
+	for index := len(comments) - 1; index >= 0; index-- {
+		comment := comments[index]
+		if !actorMatches(expected, comment.User.Login) ||
+			!strings.HasPrefix(comment.Body, "Codex Review: Didn't find any major issues.") {
+			continue
+		}
+		match := codexReviewedCommit.FindStringSubmatch(comment.Body)
+		if len(match) != 2 || !strings.EqualFold(head, match[1]) {
+			continue
+		}
+		return reviewpanel.Reviewer{
+			Name: expected, Actor: comment.User.Login, State: "CLEAN",
+			HeadSHA: strings.ToLower(head), ReviewID: comment.ID,
+		}, true
+	}
+	return reviewpanel.Reviewer{}, false
+}
+
+func actorPresent(expected string, actors []string) bool {
+	for _, actor := range actors {
+		if actorMatches(expected, actor) {
+			return true
+		}
+	}
+	return false
+}
+
+func actorMatches(expected, actor string) bool {
+	actor = strings.ToLower(strings.TrimSuffix(actor, "[bot]"))
+	// Keep aliases aligned with the reviewer names accepted by ReviewPolicyV1.
+	// Unknown policy reviewers deliberately fall back to exact actor matching.
+	aliases := map[string][]string{
+		"codex":   {"codex", "chatgpt-codex-connector"},
+		"cursor":  {"cursor"},
+		"claude":  {"claude"},
+		"copilot": {"copilot", "copilot-pull-request-reviewer", "github-copilot"},
+	}
+	values := aliases[expected]
+	if len(values) == 0 {
+		values = []string{expected}
+	}
+	for _, value := range values {
+		if actor == value {
+			return true
+		}
+	}
+	return false
+}
diff --git a/cmd/review/observe_test.go b/cmd/review/observe_test.go
new file mode 100644
index 0000000..cfdb2f0
--- /dev/null
+++ b/cmd/review/observe_test.go
@@ -0,0 +1,173 @@
+package main
+
+import (
+	"context"
+	"encoding/json"
+	"errors"
+	"io"
+	"os"
+	"path/filepath"
+	"slices"
+	"strings"
+	"testing"
+
+	"github.com/itsHabib/workbench/contracts/reviewpanel"
+)
+
+func TestBuildPanelUsesOnlyExactHeadCompletion(t *testing.T) {
+	plan := testPlan(t, "T2")
+	reviews := []rawReview{
+		review("cursor[bot]", "COMMENTED", testHeadB, 1),
+		review("cursor[bot]", "COMMENTED", testHeadA, 2),
+	}
+	comments := []issueComment{
+		comment("chatgpt-codex-connector[bot]",
+			"Codex Review: Didn't find any major issues.\n\n**Reviewed commit:** `"+testHeadA+"`", 3),
+	}
+	evidence := buildPanel(plan, reviews, comments, []string{"Copilot"})
+	if err := reviewpanel.Validate(evidence); err != nil {
+		t.Fatal(err)
+	}
+	if len(evidence.Completed) != 2 {
+		t.Fatalf("completed = %#v", evidence.Completed)
+	}
+	if len(evidence.Pending) != 0 || len(evidence.Missing) != 0 {
+		t.Fatalf("pending %v missing %v", evidence.Pending, evidence.Missing)
+	}
+}
+
+func TestCleanCommentRequiresFullExactHead(t *testing.T) {
+	comments := []issueComment{
+		comment("chatgpt-codex-connector[bot]",
+			"Codex Review: Didn't find any major issues.\n\n**Reviewed commit:** `"+testHeadA[:10]+"`", 3),
+	}
+	if _, ok := cleanComment("codex", testHeadA, comments); ok {
+		t.Fatal("abbreviated reviewed commit accepted")
+	}
+	comments[0].Body = "Codex Review: Didn't find any major issues.\n\n**Reviewed commit:** `" +
+		strings.ToUpper(testHeadA) + "`"
+	if _, ok := cleanComment("codex", testHeadA, comments); ok {
+		t.Fatal("uppercase reviewed commit accepted")
+	}
+	comments[0].Body = "Codex Review: Didn't find any major issues.\n\n**Reviewed commit:** `" + testHeadA + "`"
+	if _, ok := cleanComment("codex", testHeadA, comments); !ok {
+		t.Fatal("full exact reviewed commit rejected")
+	}
+}
+
+func TestActorMatchesConfiguredReviewerAliases(t *testing.T) {
+	tests := map[string][]string{
+		"codex":   {"codex", "chatgpt-codex-connector[bot]"},
+		"claude":  {"claude", "claude[bot]"},
+		"cursor":  {"cursor", "cursor[bot]"},
+		"copilot": {"Copilot", "copilot-pull-request-reviewer[bot]", "github-copilot"},
+	}
+	for reviewer, aliases := range tests {
+		for _, alias := range aliases {
+			if !actorMatches(reviewer, alias) {
+				t.Errorf("actorMatches(%q, %q) = false", reviewer, alias)
+			}
+		}
+	}
+}
+
+func TestBuildPanelPartitionsPendingAndMissing(t *testing.T) {
+	plan := testPlan(t, "T3")
+	evidence := buildPanel(plan, nil, nil, []string{"chatgpt-codex-connector[bot]"})
+	if err := reviewpanel.Validate(evidence); err != nil {
+		t.Fatal(err)
+	}
+	if !slices.Equal(evidence.Pending, []string{"codex"}) {
+		t.Fatalf("pending = %v", evidence.Pending)
+	}
+	if !slices.Equal(evidence.Missing, []string{"claude", "cursor"}) {
+		t.Fatalf("missing = %v", evidence.Missing)
+	}
+}
+
+func TestObserveRejectsHeadChangeWithoutPublishing(t *testing.T) {
+	temp := t.TempDir()
+	planPath := filepath.Join(temp, "plan.json")
+	writeJSON(t, planPath, testPlan(t, "T1"))
+	out := filepath.Join(temp, "panel.json")
+	headCalls := 0
+	runner := fakeRunner{run: func(_ []byte, name string, args ...string) ([]byte, error) {
+		if name == "gh" && slices.Contains(args, "view") {
+			head := testHeadA
+			if headCalls > 0 {
+				head = testHeadB
+			}
+			headCalls++
+			return []byte(`{"headRefOid":"` + head + `","state":"OPEN"}`), nil
+		}
+		if name != "gh" || !slices.Contains(args, "api") {
+			return nil, errors.New("unexpected command")
+		}
+		endpoint := args[len(args)-1]
+		if slices.Contains(args, "--slurp") {
+			return []byte(`[[]]`), nil
+		}
+		if endpoint == "repos/itshabib/ship/pulls/7/requested_reviewers" {
+			return []byte(`{"users":[]}`), nil
+		}
+		return nil, errors.New("unexpected endpoint")
+	}}
+	code := run(context.Background(), []string{
+		"observe", "-plan", planPath, "-out", out,
+	}, runner, io.Discard, io.Discard)
+	if code != exitRefused {
+		t.Fatalf("exit = %d", code)
+	}
+	if _, err := os.Stat(out); !os.IsNotExist(err) {
+		t.Fatalf("stale observation published: %v", err)
+	}
+}
+
+func review(actor, state, head string, id int64) rawReview {
+	value := rawReview{ID: id, State: state, CommitID: head}
+	value.User.Login = actor
+	value.User.Type = "Bot"
+	return value
+}
+
+func comment(actor, body string, id int64) issueComment {
+	value := issueComment{ID: id, Body: body}
+	value.User.Login = actor
+	value.User.Type = "Bot"
+	return value
+}
+
+func TestObservePublishesValidPanel(t *testing.T) {
+	temp := t.TempDir()
+	planPath := filepath.Join(temp, "plan.json")
+	writeJSON(t, planPath, testPlan(t, "T1"))
+	out := filepath.Join(temp, "panel.json")
+	runner := fakeRunner{run: func(_ []byte, name string, args ...string) ([]byte, error) {
+		if name == "gh" && slices.Contains(args, "view") {
+			return []byte(`{"headRefOid":"` + testHeadA + `","state":"OPEN"}`), nil
+		}
+		endpoint := args[len(args)-1]
+		switch endpoint {
+		case "repos/itshabib/ship/pulls/7/reviews":
+			value := review("chatgpt-codex-connector[bot]", "COMMENTED", testHeadA, 9)
+			data, _ := json.Marshal([][]rawReview{{value}})
+			return data, nil
+		case "repos/itshabib/ship/issues/7/comments":
+			return []byte(`[[]]`), nil
+		case "repos/itshabib/ship/pulls/7/requested_reviewers":
+			return []byte(`{"users":[]}`), nil
+		}
+		return nil, errors.New("unexpected endpoint")
+	}}
+	code := run(context.Background(), []string{
+		"observe", "-plan", planPath, "-out", out,
+	}, runner, io.Discard, io.Discard)
+	if code != exitOK {
+		t.Fatalf("exit = %d", code)
+	}
+	var evidence reviewpanel.Evidence
+	readJSON(t, out, &evidence)
+	if err := reviewpanel.Validate(evidence); err != nil {
+		t.Fatal(err)
+	}
+}
