+		PlanID:        "rp_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
+		Cycle:         1,
+		CurrentTier:   "T1",
+		Findings: []FindingState{{
+			ID: "f1", Severity: "low", Reviewers: []string{"codex"},
